package com.gomgomapps.math.core;
import java.math.*;import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class PublicDecimalMeasureStoriesTest {
 @Test public void sixThousandMixedQuantityCasesIgnoreSavedKeys(){Checker c=new Checker();int count=0;for(String unit:List.of("m","L","kg"))for(String id:List.of(DecimalMeasureStories.ADD,DecimalMeasureStories.SUB))for(int n=0;n<1000;n++){int a=n,b=n*37%1000;if(id.equals(DecimalMeasureStories.SUB)&&a<b){int t=a;a=b;b=t;}String x=BigDecimal.valueOf(a,3).toPlainString(),y=BigDecimal.valueOf(b,3).toPlainString();Question q=DecimalMeasureStories.make(id,x,y,unit);q.answers=new String[]{"poison"};q.expression="poison";String answer=BigDecimal.valueOf(id.equals(DecimalMeasureStories.ADD)?a+b:a-b,3).toPlainString();assertTrue(c.check(q,List.of(),List.of(answer)).correct());assertEquals(Checker.Status.WRONG_ANSWER,c.check(q,List.of(),List.of(new BigDecimal(answer).add(new BigDecimal("0.001")).toPlainString())).status);assertEquals(unit,DecimalMeasureStories.read(q).unit());count++;}assertEquals(6000,count);}
 @Test public void massHelpUsesVisibleRelationAndNeverTransfers(){for(String id:List.of(DecimalMeasureStories.ADD,DecimalMeasureStories.SUB)){Question q=DecimalMeasureStories.make(id,"1.005","0.09","kg");q.answers=new String[]{"999"};q.expression="poison";boolean add=id.equals(DecimalMeasureStories.ADD);HelpPlan h=HelpPlan.forQuestion(q);assertEquals(9,h.size());assertFalse(h.canTransfer());List<String> values=List.of(add?"add":"sub","1.005","0.09","3","1000","1005","90",add?"1095":"915",add?"1.095":"0.915");for(int i=0;i<9;i++){assertTrue(h.step(i).accepts(values.get(i)));assertEquals("",h.step(i).after);}assertEquals("decimal-measure-story-v1",q.studyGuide.teachingVersion);assertTrue(h.restore(null,q.id).entries.stream().allMatch(String::isEmpty));}}
 @Test public void invalidOrWrongUnitInputDoesNotFallBack(){Checker c=new Checker();Question q=DecimalMeasureStories.make(DecimalMeasureStories.ADD,"0.000","0.0","kg");assertTrue(c.check(q,List.of(),List.of("0")).correct());for(String input:List.of("1/1","0 kg",""))assertEquals(Checker.Status.INPUT_NEEDED,c.check(q,List.of(),List.of(input)).status);assertEquals(Checker.Status.INPUT_NEEDED,c.check(q,List.of(),Arrays.asList((String)null)).status);assertEquals(Checker.Status.INPUT_NEEDED,c.check(new Question(q.skillId,"broken","","0"),List.of(),List.of("0")).status);}
}
